def _f(typ, date, az, name):
    """Fundstelle für Entscheidungen, deren Name im Korpus fehlt oder verstümmelt ist (z. B. „: ja“)."""
    return f"BGH, {typ} vom {date[8:]}.{date[5:7]}.{date[:4]} – {az} – {name}"


